// Explicit anonymous network check, downloads only to a marked fixture cache.
using System;using System.IO;using System.Linq;using System.Threading;using System.Collections.Generic;using DynastyCOT.Collection;
class CollectionPublishedDownloads {
 static int Main(string[] args){try{string source=Path.GetFullPath(args[0]),root=Path.GetFullPath(args[1]);var fixture=new Fixture(root,Path.GetDirectoryName(root));var catalog=Json.Read<Catalog>(Path.Combine(source,"Packaging/Collection/catalog.json"));catalog.Validate();File.WriteAllText(Path.Combine(root,"MMCModManager.exe"),"fixture only; never executed");var client=new Downloads();var prepared=new List<PreparedModule>();foreach(var module in catalog.Modules){var releases=client.Check(module,CancellationToken.None);var pinned=releases.SingleOrDefault(x=>x.Version==module.Current.Version);if(pinned==null||pinned.ArchiveSha256!=module.Current.ArchiveSha256)throw new IOException("Pinned published release unavailable/different: "+module.Id);var ready=client.Prepare(module,pinned,Path.Combine(fixture.Root,"PublicDownloads"),CancellationToken.None,Console.WriteLine);if(Paths.HashFile(ready.Dll)!=module.Current.DllSha256)throw new IOException("Published plugin differs from the exact standalone.");prepared.Add(ready);Console.WriteLine("PASS "+module.Id+" "+pinned.Version+": anonymous discovery, proof, ZIP/DLL hashes and three-file layout.");}var installer=new CollectionInstaller(catalog,fixture);var plan=installer.Install(root,prepared.ToDictionary(x=>x.Module.Id,x=>x.Release),prepared);installer.Execute(plan,new Dictionary<string,string>(),Console.WriteLine);foreach(var p in prepared)if(Paths.HashFile(Paths.Resolve(root,"Plugins/"+p.Module.FileName))!=p.Release.DllSha256)throw new IOException("Installed fixture bytes differ.");
 var g=catalog.Get("GamedayAtmosphere");var previous=client.Check(g,CancellationToken.None).First(x=>x.Version=="2.1.9");var old=client.Prepare(g,previous,Path.Combine(fixture.Root,"PublicDownloads"),CancellationToken.None,Console.WriteLine);string btf=Paths.HashFile(Paths.Resolve(root,"Plugins/BeyondTheField.dll"));var update=installer.Install(root,new Dictionary<string,ModuleRelease>{{g.Id,old.Release}},new[]{old},new HashSet<string>{g.Id});string backup=installer.Execute(update,new Dictionary<string,string>(),Console.WriteLine);if(Paths.HashFile(Paths.Resolve(root,"Plugins/BeyondTheField.dll"))!=btf)throw new IOException("Independent GDA change touched BTF.");installer.Restore(root,backup);if(Paths.HashFile(Paths.Resolve(root,"Plugins/GamedayAtmosphere.dll"))!=g.Current.DllSha256)throw new IOException("Published-payload fixture rollback failed.");Console.WriteLine("PASS public discovery/download/four-module fixture install, independent GDA version change and rollback; BTF unchanged. No live installation.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
